actions.script:
if (!personFound) return
const L = (text) => ec.l10n.localize(text)
const orgs = []
for (const row of ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId).condition('relationshipTypeEnumId', 'in', ['PrtEmployee', 'PrtContractor'])
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()) {
    const org = ec.entity.find('mantle.party.Organization').condition('partyId', row.toPartyId).disableAuthz().one()
    if (org?.organizationName) orgs.push(org.organizationName)
}
captionText = Array.from(new Set(orgs)).join(', ')
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
canRequest = !!ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('ALLOCATION_APPROVE') || Array.from(vis.managedProjectIds || []).length > 0)
const enc = (value) => String(value == null ? '' : value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\u0022/g, '&quot;')
avatarHtml = '<m-avatar name="' + enc(person.name) + '"' + (person.userId ? ' user-id="' + enc(person.userId) + '"' : '')
        + ' size="40px" class="q-mr-md"></m-avatar>'
// People P2: the employee record, for a viewer People's scope admits
ec.message.pushErrors()
try {
    employeeLink = ec.service.sync().name('ironstone.people.ContextServices.get#Employee360Link').parameters({partyId}).call() || {}
} catch (error) {
    employeeLink = {}
} finally { ec.message.clearErrors(); ec.message.popErrors() }
